function normalizarCodigo(codigo: string) {
  return String(codigo ?? "").toUpperCase().replace(/[^A-Z0-9]/g, "");
}

const POR_CODIGO = new Map(ITENS.map((item) => [normalizarCodigo(item.codigo), item] as const));

export function consultarCatalogoSampelFrasle(codigo: string) {
  return POR_CODIGO.get(normalizarCodigo(codigo)) || null;
}
